"""Generate the component study report from sealed native SQLite and independent reference outcomes."""
from project import D,read


def num(x,places=2):
    return f"{x:.{places}f}".replace(".",",")


def interval(r,kind):
    lo,hi=r[kind+"_ci"]
    return f"+{num(100*r[kind+'_delta'])} п.п. [{num(100*lo)} – {num(100*hi)}]"


def main():
    rr=read(D/"results.json")["groups"];run=read(D/"native-run.json");pilot=read(D/"pilot-decision.json")
    m=rr["main"];a=rr["all"]
    lines=["# Исходная инвалидация MemTrace после правок файлов",
       f"Реальный SemanticStore из открытого MemTrace после {a['n']} подтверждённых изменений сохранил весь прежний пакет в **{a['db_active_packets']}** событиях. При отдельном пересчёте по интервалам предыдущий порядок и состав сохранились в {a['range_same_packets']}, из них **{a['strict_range_packets']}** выдержали последующую проверку байтов изменённого пути. Одинаковые исходные блоки и действия использовались во всех условиях. [Протокол](PROTOCOL_RU.md) · [Индивидуальные SQL-результаты](native-projections.json.gz) · [Исходный байтовый аудит](../span_updates/audit_strict_rows.json.gz)",
       "| Набор | События / задачи | Прежний пакет целиком активен в SQLite | Та же выдача после интервального обновления | Включая сверку байтов | Разность по событиям, 95% ДИ | Разность при равном весе задач, 95% ДИ |",
       "|---|---:|---:|---:|---:|---:|---:|"]
    for group,name in (("main","Основные запуски"),("additional","Дополнительные запуски тех же задач"),("all","Всего")):
        t=rr[group]
        lines.append(f"| {name} | {t['n']} / {t['issues']} | {t['db_active_packets']} | {t['range_same_packets']} | {t['strict_range_packets']} | {interval(t,'micro')} | {interval(t,'macro')} |")
    lines.extend(["",
      f"На всех {a['n']} событиях фактическое множество закрытых строк в SQLite совпало с авторским предикатом и файловым правилом. Каждой закрытой строке соответствовало реальное ребро INVALIDATED_BY, запись и история остались в базе. В основной группе строже проверенная выдача дала {m['strict_wins']} парных выигрышей и {m['strict_losses']} проигрышей по повторному использованию целого пакета. Интервалы получены 10 000 перевыборками целых задач с возвращением; дополнительные траектории используют те же задачи. [Численные результаты](results.json) · [Код оценки](grade.py)","",
      f"Исходный компонент обработал {a['block_occurrences']:,} вхождений старых блоков. Он закрыл {a['closed_block_occurrences']:,} из них, или {a['closed_bytes']:,} из {a['selected_bytes']:,} байтов исходной выборки. В старой ревизии осталось {a['old_active']:,} активных вхождений. Новый точный запрос со старыми ключами получил {a['new_intent_old_key_hits']} попаданий. Суммы учитывают повторные чтения и не являются уникальными байтами проекта или физическим I/O. Две оригинальные проверки авторов выполнены без изменения кода. В отдельной SQLite с двумя символами одного файла, объектом самого файла и другим файлом указание одного изменённого символа закрыло один объект, указание целого файла закрыло три. [Авторские тесты и диагностика](fixtures.json) · [Нативный запуск](replay.py)","",
      "**Что именно проверяет сравнение.** Для каждого прежнего фрагмента создана запись CODE_OBSERVATION с идентификатором файла и отличимой семантической ролью. В SemanticStore.advance_workspace_revision передан один изменившийся файл. Интервальный алгоритм дополнительно использует границы замены из того же события. SDK распознаёт точные идентификаторы файлов, символов и тестов; для смещений произвольного блока в этой операции отдельного поля нет. Если известны надёжные события на уровне символа, фактическая гранулярность MemTrace может повыситься. Даже непогашенную запись со старой ревизией исходный ContextAssembler помечает при восстановлении на новой ревизии как историческую и требующую повторной проверки. Прежние метки активности SQLite и полная текущая выдача относятся к разным шагам. [Обновление ревизии, строки 857–1008](https://github.com/Homy-Xu/MemTrace/blob/5508f8be81025d8aa90726b1e06aef4ea484e577/src/memtrace/semantic_memory/store.py#L857-L1008) · [Контракт идентификаторов](https://github.com/Homy-Xu/MemTrace/blob/5508f8be81025d8aa90726b1e06aef4ea484e577/src/memtrace/semantic_memory/store.py#L1009-L1025) · [Маркировка при чтении](https://github.com/Homy-Xu/MemTrace/blob/5508f8be81025d8aa90726b1e06aef4ea484e577/src/memtrace/recall/assembler.py#L65-L80)","",
      f"Первые 64 транзакции заранее фиксированы по хешу идентификаторов. При медиане {num(pilot['median_s'],3)} с на событие эксперимент продолжился на всей панели. Время обработки составило {num(run['elapsed_s']/60,1)} мин, включая создание отдельного хранилища, страницы, SQL-проверки и освобождение файлов на каждом событии. Этот показатель относится к проверочной установке. [Условие продолжения](pilot-decision.json) · [Воспроизведение](REPRODUCE_RU.md)","",
      "**Как это соотносится с предыдущей работой.** R10 уже использовал нативный MemTrace для хранения и восстановления результатов тестов с разными ревизиями и реального повторного исполнения pytest. Там оценивалась достоверность 418 выводов о тестах, здесь — инвалидация чтений исходного текста при 2 696 подтверждённых действиях Handoff Debt. Числа интервального контроля были известны из R40/span_updates. Новое наблюдение подтверждает, что их файловый компаратор при заданных входах действительно реализуется реальным SQL-компонентом MemTrace. Доступны только участки затронутого файла; другие пути считаются фиксированными. Проверка не измеряет конечное качество действий LLM или обобщение на новые репозитории. [Нативные испытания R10](../../graph_memory_round10/provenance/README_RU.md) · [Первоначальный эксперимент с диапазонами](../span_updates/REPORT_RU.md) · [Статья MemTrace](https://arxiv.org/abs/2610.04838) · [Handoff Debt](https://aclanthology.org/2026.emnlp-main.738/)"])
    (D/"REPORT_RU.md").write_text("\n".join(lines[:1])+ "\n\n"+lines[1]+"\n\n"+"\n".join(lines[2:])+"\n",encoding="utf8")


if __name__=="__main__":main()

